    42→    if (!byFile.has(file)) {
    43→      byFile.set(file, []);
    44→    }
    45→    byFile.get(file)!.push(item);
    46→  }
    47→
    48→  // For each file, determine parent relationships based on path
    49→  for (const [, fileItems] of byFile) {
    50→    // Sort by path length (shorter paths are potential parents)
    51→    const sorted = [...fileItems].sort((a, b) => {
    52→      const aLen = a._path?.length || 0;
    53→      const bLen = b._path?.length || 0;
    54→      return aLen - bLen;
    55→    });
    56→
    57→    for (const item of sorted) {
    58→      const itemPath = item._path;
    59→
    60→      if (!itemPath) {
    61→        // Root item in file - no parent
    62→        parentMap.set(item._ulid, undefined);
    63→        continue;
    64→      }
    65→
    66→      // Find the closest parent by matching path prefix
    67→      // Path format: "features[0].requirements[0]"
    68→      // Parent path: "features[0]" or undefined (root item)
    69→      const lastDot = itemPath.lastIndexOf('.');
    70→      const parentPath = lastDot > -1 ? itemPath.substring(0, lastDot) : undefined;
    71→
    72→      // Find parent item
    73→      let parentUlid: string | undefined;
    74→      if (parentPath === undefined) {
    75→        // Direct child of the root item (the item with no path)
    76→        const rootItem = fileItems.find(i => !i._path);
    77→        parentUlid = rootItem?._ulid;
    78→      } else {
    79→        // Find item with matching parent path
